-- ---------------------------------------------------------------------------
-- 1) Course catalog: everything the course pages show, per course, EN + AR.
-- ---------------------------------------------------------------------------
alter table public.courses
  add column if not exists slug text,
  add column if not exists short_title jsonb not null default '{"en": "", "ar": ""}'::jsonb,
  add column if not exists category jsonb not null default '{"en": "", "ar": ""}'::jsonb,
  add column if not exists summary jsonb not null default '{"en": "", "ar": ""}'::jsonb,
  add column if not exists age_range text,
  add column if not exists image_url text,
  add column if not exists logo_url text,
  add column if not exists fallback_image_url text,
  add column if not exists tools jsonb not null default '[]'::jsonb,
  add column if not exists outcomes jsonb not null default '{"en": [], "ar": []}'::jsonb,
  add column if not exists projects jsonb not null default '{"en": [], "ar": []}'::jsonb,
  add column if not exists levels jsonb not null default '{"en": [], "ar": []}'::jsonb,
  add column if not exists faqs jsonb not null default '{"en": [], "ar": []}'::jsonb,
  add column if not exists guide jsonb not null default '{"en": [], "ar": []}'::jsonb,
  add column if not exists seo_title jsonb not null default '{"en": "", "ar": ""}'::jsonb,
  add column if not exists seo_description jsonb not null default '{"en": "", "ar": ""}'::jsonb,
  add column if not exists page_url jsonb not null default '{"en": "", "ar": ""}'::jsonb,
  add column if not exists sort_order integer not null default 0,
  add column if not exists active boolean not null default true;
create unique index if not exists courses_slug_idx on public.courses(slug) where slug is not null;

-- Existing rows keep their ids (leads and lessons point at them): they are
-- matched by name and given a slug; a course that doesn't exist yet is inserted.
-- Scratch Programming for Kids
update public.courses set slug = 'scratch'
where slug is null and name_en ilike '%scratch%'
  and not exists (select 1 from public.courses where slug = 'scratch')
  and id = (select id from public.courses where slug is null and name_en ilike '%scratch%' order by created_at limit 1);
insert into public.courses (slug, name_en, name_ar)
select 'scratch', $t$Scratch Programming for Kids$t$, $t$برمجة Scratch للأطفال$t$
where not exists (select 1 from public.courses where slug = 'scratch');
update public.courses set
  name_en = $t$Scratch Programming for Kids$t$,
  name_ar = $t$برمجة Scratch للأطفال$t$,
  description = $j${"en":"A friendly first step into coding through visual blocks, stories, games, and creative problem solving.","ar":"بداية سهلة وممتعة لعالم البرمجة من خلال البلوكات البصرية والقصص والألعاب وحل المشكلات."}$j$::jsonb,
  summary = $j${"en":"A friendly first step into coding through visual blocks, stories, games, and creative problem solving.","ar":"بداية سهلة وممتعة لعالم البرمجة من خلال البلوكات البصرية والقصص والألعاب وحل المشكلات."}$j$::jsonb,
  category = $j${"en":"Programming","ar":"برمجة"}$j$::jsonb,
  short_title = $j${"en":"Scratch","ar":"Scratch"}$j$::jsonb,
  age_range = $t$8-12$t$,
  min_age = 8,
  max_age = 12,
  icon = $t$scratch$t$,
  image_url = $t$https://images.unsplash.com/photo-1509062522246-3755977927d7?auto=format&fit=crop&w=1400&q=80$t$,
  logo_url = $t$https://schowl.com/courses/scratch.svg$t$,
  fallback_image_url = $t$https://schowl.com/courses/scratch_bg.png$t$,
  tools = $j$["Scratch","Logic","Storytelling","Games"]$j$::jsonb,
  outcomes = $j${"en":["Understand sequencing, loops, events, and conditions.","Build interactive stories and simple games.","Practice creative thinking and debugging."],"ar":["فهم التسلسل والتكرار والأحداث والشروط.","بناء قصص تفاعلية وألعاب بسيطة.","تدريب التفكير الإبداعي وحل الأخطاء."]}$j$::jsonb,
  projects = $j${"en":["Maze game","Animated story","Quiz game"],"ar":["لعبة متاهة","قصة متحركة","لعبة أسئلة"]}$j$::jsonb,
  levels = $j${"en":[{"title":"Foundations","description":"Blocks, motion, events, and visual logic."},{"title":"Interactive Projects","description":"Games and stories with scoring, rules, and feedback."}],"ar":[{"title":"الأساسيات","description":"البلوكات والحركة والأحداث والمنطق البصري."},{"title":"مشاريع تفاعلية","description":"ألعاب وقصص فيها نقاط وقواعد وتفاعل."}]}$j$::jsonb,
  faqs = $j${"en":[{"question":"Is Scratch good for beginners?","answer":"Yes. Scratch is the best starting point for younger students who are new to coding."},{"question":"What will my child be able to build?","answer":"Students build small games, animated stories, quizzes, and interactive scenes while learning core programming logic."},{"question":"Does Scratch prepare students for Python?","answer":"Yes. It teaches sequencing, loops, conditions, events, and debugging before students move to typed code."},{"question":"What device does the student need?","answer":"A laptop or desktop with a stable internet connection is best so the student can share their screen and build comfortably."},{"question":"Can my 8-year-old keep up in an online Scratch class?","answer":"Yes. Scratch is built for young learners, and classes are one-on-one or at most four students, so the teacher can slow down, repeat a step, or help with the mouse and screen sharing. The trial lesson also shows how comfortable your child is before joining."},{"question":"Does my child need to be good at math to learn Scratch?","answer":"No. Scratch uses simple ideas like counting, positions on the screen and keeping score, and these are explained through the project itself. Children often find that numbers start to make sense when they have a purpose inside their own game."},{"question":"How do we start the Scratch course?","answer":"Book a trial lesson. The teacher meets your child, checks their level and interests, and recommends whether to begin with Foundations or move faster into interactive projects."}],"ar":[{"question":"هل Scratch مناسب للمبتدئين؟","answer":"نعم. Scratch من أفضل البدايات للطلاب الأصغر سنًا والجدد في البرمجة."},{"question":"ماذا سيستطيع طفلي أن يبني؟","answer":"يبني الطلاب ألعابًا صغيرة وقصصًا متحركة وأسئلة تفاعلية ومشاهد بسيطة أثناء تعلم منطق البرمجة."},{"question":"هل Scratch يمهد لتعلم Python؟","answer":"نعم. يتعلم الطالب التسلسل والتكرار والشروط والأحداث وحل الأخطاء قبل الانتقال إلى كتابة الكود."},{"question":"ما الجهاز المطلوب للحصة؟","answer":"الأفضل استخدام لابتوب أو كمبيوتر مع إنترنت مستقر حتى يشارك الطالب الشاشة ويطبق بسهولة."},{"question":"هل يستطيع طفل في الثامنة متابعة حصة Scratch أونلاين؟","answer":"نعم. صُمم Scratch للمتعلمين الصغار، والحصص فردية أو في مجموعات لا تزيد على أربعة طلاب، فيستطيع المعلم أن يبطئ الإيقاع ويعيد الخطوة ويساعد الطفل في استخدام الفأرة ومشاركة الشاشة. كما تكشف الحصة التجريبية مدى استعداد الطفل قبل البدء."},{"question":"هل يجب أن يكون طفلي متفوقًا في الرياضيات ليتعلم Scratch؟","answer":"لا. يعتمد Scratch على أفكار بسيطة مثل العد ومواضع الشخصيات على الشاشة وحساب النقاط، وتُشرح هذه الأفكار من خلال المشروع نفسه. وكثيرًا ما يجد الطفل أن للأرقام معنى حين يستخدمها داخل لعبته."},{"question":"كيف نبدأ كورس Scratch؟","answer":"احجز حصة تجريبية؛ يتعرف فيها المعلم إلى الطفل ويحدد مستواه واهتماماته، ثم يقترح البدء من مستوى الأساسيات أو التقدم أسرع نحو المشاريع التفاعلية."}]}$j$::jsonb,
  guide = $j${"en":[{"heading":"Who this Scratch course for kids is for","body":"Schowl's Scratch course for kids is designed for children aged 8 to 12 who are completely new to coding. No typing speed, math background or previous programming experience is needed. If your child can read simple instructions and use a mouse, they are ready to start.\n\nIt suits the child who loves making up stories, drawing characters or inventing rules for games, and also the child who always asks how things work. Scratch turns those instincts into code by snapping colourful blocks together, so children see the result of every idea on screen straight away."},{"heading":"What a live 60-minute Scratch class looks like","body":"Every class is 60 minutes, live online with a real teacher, either one-on-one or in a small group of no more than four students. A typical session opens with a quick look at last week's project and a short warm-up question. The teacher then introduces one new idea, such as a loop or an event, and builds a tiny example while sharing the screen.\n\nMost of the hour belongs to the student. Children share their own screens, build their part of the project, test it and fix what breaks, with the teacher guiding rather than taking over. The class ends with each student showing what they made, explaining one choice they made and hearing what to try next."},{"heading":"How the course progresses: from blocks to interactive games","body":"The course moves through two levels. In Foundations, students learn blocks, motion, events and visual logic: making a sprite move, respond to a key press, change costume and talk to other sprites. Along the way they meet sequencing, loops and conditions, the same ideas that power every programming language.\n\nIn Interactive Projects, those ideas come together in games and stories with scoring, rules and feedback. Students build a maze game where touching a wall sends the player back to the start, an animated story with scenes and dialogue, and a quiz game that keeps score and reacts to right and wrong answers. Each project is finished, tested and presented, which is where debugging and creative thinking really grow."},{"heading":"What your child needs and how parents follow progress","body":"Your child needs a laptop or desktop computer with a stable internet connection, a web browser to open Scratch and, ideally, headphones with a microphone. Screen sharing is used in every class so the teacher can see exactly what the student is building and help in real time.\n\nParents are not left guessing. Students work on weekly projects, receive instructor feedback on them, and families get parent-friendly progress updates that explain what was learned in plain language. The course ends with a final project your child can show and explain to you, plus a certificate on completion. Scheduling is flexible, so classes can fit around school and other activities."},{"heading":"What to learn after Scratch","body":"Once a child is comfortable with loops, conditions and events in Scratch, typed code is the natural next step. For students aged 10 and up, that step is Schowl's Python & AI Foundations course, where the same logic is written as real Python and applied to games, tools and beginner AI experiments.\n\nChildren who mostly enjoyed building games can instead continue with the Game Development course, which grows the same ideas into levels, collisions and scoring. The best route can be discussed with the teacher based on the final project."}],"ar":[{"heading":"لمن صُمم كورس سكراتش للأطفال؟","body":"كورس سكراتش للأطفال في Schowl موجّه للأطفال من 8 إلى 12 سنة الذين يخطون خطوتهم الأولى في البرمجة. لا يحتاج الطفل إلى خبرة سابقة أو مهارة في الكتابة السريعة أو مستوى معين في الرياضيات؛ يكفي أن يستطيع قراءة تعليمات بسيطة واستخدام الفأرة.\n\nيناسب الكورس الطفل الذي يحب تأليف القصص ورسم الشخصيات واختراع قواعد للألعاب، كما يناسب الطفل الفضولي الذي يسأل دائمًا كيف تعمل الأشياء. ففي Scratch تتحول الأفكار إلى برامج بتركيب بلوكات ملونة، فيرى الطفل نتيجة كل فكرة على الشاشة فورًا."},{"heading":"كيف تسير حصة Scratch المباشرة ذات الستين دقيقة؟","body":"مدة كل حصة 60 دقيقة، وتُقدَّم أونلاين بشكل مباشر مع معلم حقيقي، إما فرديًا أو في مجموعة صغيرة لا تزيد على أربعة طلاب. تبدأ الحصة عادةً بمراجعة سريعة لمشروع الأسبوع الماضي وسؤال تمهيدي قصير، ثم يشرح المعلم فكرة جديدة واحدة، مثل التكرار أو الأحداث، ويبني مثالًا صغيرًا وهو يشارك شاشته.\n\nأما معظم الوقت فللطالب نفسه: يشارك شاشته، ويبني جزءه من المشروع، ويجرّبه، ويصلح ما يتعطل بتوجيه من المعلم دون أن يعمل المعلم بدلًا منه. وفي الختام يعرض كل طالب ما أنجزه ويشرح قرارًا اتخذه، ويعرف ما الذي سيجربه في المرة القادمة."},{"heading":"مراحل الكورس: من البلوكات إلى الألعاب التفاعلية","body":"ينقسم الكورس إلى مستويين. في مستوى الأساسيات يتعلم الطالب البلوكات والحركة والأحداث والمنطق البصري: كيف يحرك شخصية، ويجعلها تستجيب لضغطة زر، وتغيّر مظهرها، وتتحاور مع شخصيات أخرى. وخلال ذلك يتعرف إلى التسلسل والتكرار والشروط، وهي المفاهيم نفسها التي تقوم عليها لغات البرمجة كلها.\n\nوفي مستوى المشاريع التفاعلية تجتمع هذه المفاهيم في ألعاب وقصص فيها نقاط وقواعد وتفاعل؛ فيبني الطالب لعبة متاهة تعيد اللاعب إلى البداية إذا لمس الجدار، وقصة متحركة بمشاهد وحوارات، ولعبة أسئلة تحسب النقاط وتتفاعل مع الإجابات الصحيحة والخاطئة. ويُختبر كل مشروع ويُعرض كاملًا، وهنا تنمو مهارة حل الأخطاء والتفكير الإبداعي."},{"heading":"ما يحتاجه الطفل وكيف يتابع ولي الأمر تقدمه","body":"يحتاج الطفل إلى لابتوب أو كمبيوتر مكتبي مع اتصال إنترنت مستقر، ومتصفح لفتح Scratch، ويُفضَّل استخدام سماعة بميكروفون. وتُستخدم مشاركة الشاشة في كل حصة ليرى المعلم ما يبنيه الطالب بدقة ويساعده في اللحظة نفسها.\n\nولا يبقى ولي الأمر بعيدًا عن الصورة؛ فالطالب يعمل على مشروع أسبوعي ويتلقى ملاحظات المعلم عليه، وتصل الأسرة تقارير متابعة واضحة تشرح ما تعلمه الطفل بلغة بسيطة. وينتهي الكورس بمشروع نهائي يعرضه الطفل ويشرحه لأسرته، مع شهادة إتمام. كما أن المواعيد مرنة بما يناسب الدراسة والأنشطة الأخرى."},{"heading":"ماذا يتعلم الطفل بعد Scratch؟","body":"عندما يتقن الطفل التكرار والشروط والأحداث في Scratch يصبح الانتقال إلى كتابة الكود خطوة طبيعية. فالطالب الذي بلغ العاشرة يمكنه الانتقال إلى كورس أساسيات Python والذكاء الاصطناعي في Schowl، حيث يكتب المنطق نفسه بلغة Python ويطبقه في ألعاب وأدوات وتجارب أولية في الذكاء الاصطناعي.\n\nأما الطفل الذي استمتع ببناء الألعاب أكثر من غيرها فيمكنه متابعة كورس تطوير الألعاب، الذي يطوّر الأفكار نفسها إلى مراحل وتصادم ونقاط. ويمكن تحديد المسار الأنسب مع المعلم بناءً على المشروع النهائي."}]}$j$::jsonb,
  seo_title = $j${"en":"Scratch Course for Kids in Egypt | Schowl","ar":"كورس Scratch للأطفال في مصر | Schowl"}$j$::jsonb,
  seo_description = $j${"en":"Live Scratch programming classes for kids aged 8-12. Build games, stories, and beginner coding confidence with Schowl.","ar":"حصص لايف لتعليم Scratch للأطفال من 8 إلى 12 سنة لبناء ألعاب وقصص ومهارات برمجة أولية مع Schowl."}$j$::jsonb,
  page_url = $j${"en":"https://schowl.com/course/scratch/","ar":"https://schowl.com/ar/course/scratch/"}$j$::jsonb,
  sort_order = 1,
  active = true,
  updated_at = now()
where slug = 'scratch';

-- Python & AI Foundations
update public.courses set slug = 'python'
where slug is null and name_en ilike '%python%'
  and not exists (select 1 from public.courses where slug = 'python')
  and id = (select id from public.courses where slug is null and name_en ilike '%python%' order by created_at limit 1);
insert into public.courses (slug, name_en, name_ar)
select 'python', $t$Python & AI Foundations$t$, $t$أساسيات Python والذكاء الاصطناعي$t$
where not exists (select 1 from public.courses where slug = 'python');
update public.courses set
  name_en = $t$Python & AI Foundations$t$,
  name_ar = $t$أساسيات Python والذكاء الاصطناعي$t$,
  description = $j${"en":"A practical path for students ready to write real code, solve problems, and understand beginner AI ideas through projects.","ar":"مسار عملي للطلاب المستعدين لكتابة كود حقيقي وحل المشكلات وفهم أفكار أولية في الذكاء الاصطناعي من خلال المشاريع."}$j$::jsonb,
  summary = $j${"en":"A practical path for students ready to write real code, solve problems, and understand beginner AI ideas through projects.","ar":"مسار عملي للطلاب المستعدين لكتابة كود حقيقي وحل المشكلات وفهم أفكار أولية في الذكاء الاصطناعي من خلال المشاريع."}$j$::jsonb,
  category = $j${"en":"Programming","ar":"برمجة"}$j$::jsonb,
  short_title = $j${"en":"Python & AI","ar":"Python وAI"}$j$::jsonb,
  age_range = $t$10-18$t$,
  min_age = 10,
  max_age = 18,
  icon = $t$python$t$,
  image_url = $t$https://images.unsplash.com/photo-1515879218367-8466d910aaa4?auto=format&fit=crop&w=1400&q=80$t$,
  logo_url = $t$https://schowl.com/courses/python.svg$t$,
  fallback_image_url = $t$https://schowl.com/courses/py.png$t$,
  tools = $j$["Python","Pygame","Beginner AI","Problem Solving"]$j$::jsonb,
  outcomes = $j${"en":["Use variables, loops, functions, and conditions.","Think through problems step by step.","Build games, tools, and beginner AI experiments."],"ar":["استخدام المتغيرات والتكرار والدوال والشروط.","حل المشكلات خطوة بخطوة.","بناء ألعاب وأدوات وتجارب أولية في الذكاء الاصطناعي."]}$j$::jsonb,
  projects = $j${"en":["Number guessing game","Simple calculator","Pygame challenge","AI prompt helper"],"ar":["لعبة تخمين الأرقام","آلة حاسبة بسيطة","تحدي Pygame","مساعد أوامر ذكاء اصطناعي"]}$j$::jsonb,
  levels = $j${"en":[{"title":"Core Python","description":"Syntax, logic, functions, and simple programs."},{"title":"Applied Projects","description":"Games and tools that combine multiple concepts."}],"ar":[{"title":"أساسيات Python","description":"القواعد والمنطق والدوال والبرامج البسيطة."},{"title":"مشاريع تطبيقية","description":"ألعاب وأدوات تجمع أكثر من مفهوم."}]}$j$::jsonb,
  faqs = $j${"en":[{"question":"Does Python require previous Scratch experience?","answer":"No. Scratch helps younger students, but Python can also start from zero for older learners."},{"question":"Is this an AI course or a coding course?","answer":"It is a coding-first course with beginner AI concepts introduced through simple, age-appropriate projects."},{"question":"What makes Python useful for teens?","answer":"Python is readable and widely used, so students can build games, tools, automations, and later explore data or AI."},{"question":"How hard is the course?","answer":"The first level starts with fundamentals, then the difficulty grows as students become more confident with projects."},{"question":"Is 10 too young to start Python?","answer":"Ten is the starting age for this course. Younger students begin with a calmer pace and shorter programs, and the small class size lets the teacher adjust to each student. If the trial lesson shows that visual blocks would be a better start, the teacher will say so and suggest Scratch."},{"question":"Will students let AI tools write their code?","answer":"The course is coding-first, so students learn to write and debug Python themselves. Beginner AI ideas are introduced through projects like the AI prompt helper, which helps students understand how AI tools respond to instructions instead of treating them as magic."},{"question":"Can learning Python help with school subjects?","answer":"Python practice strengthens step-by-step reasoning, careful reading and working with numbers, which are useful in many subjects. The course focuses on skills and projects rather than promising specific grades."}],"ar":[{"question":"هل يحتاج Python خبرة سابقة في Scratch؟","answer":"لا. Scratch مفيد للطلاب الأصغر، لكن Python يمكن أن يبدأ من الصفر للطلاب الأكبر."},{"question":"هل هذا كورس ذكاء اصطناعي أم برمجة؟","answer":"هو كورس برمجة أولًا، مع إدخال مبادئ بسيطة ومناسبة للعمر في الذكاء الاصطناعي من خلال مشاريع عملية."},{"question":"لماذا Python مفيد للمراهقين؟","answer":"Python واضح ومستخدم على نطاق واسع، ويمكن للطالب بناء ألعاب وأدوات وأتمتة ثم التوسع لاحقًا في البيانات أو الذكاء الاصطناعي."},{"question":"هل الكورس صعب؟","answer":"المستوى الأول يبدأ بالأساسيات، ثم تزيد الصعوبة تدريجيًا مع زيادة ثقة الطالب في بناء المشاريع."},{"question":"هل سن العاشرة مبكرة لتعلم Python؟","answer":"العاشرة هي سن البداية في هذا الكورس. يبدأ الطلاب الأصغر بإيقاع أهدأ وبرامج أقصر، ويتيح صغر حجم المجموعة للمعلم أن يراعي مستوى كل طالب. وإذا أظهرت الحصة التجريبية أن البلوكات البصرية بداية أنسب، فسيقترح المعلم البدء بـ Scratch."},{"question":"هل يعتمد الطلاب على أدوات الذكاء الاصطناعي في كتابة الكود؟","answer":"الكورس قائم على البرمجة أولًا، فيتعلم الطالب كتابة كود Python وتصحيحه بنفسه. أما مبادئ الذكاء الاصطناعي فتُقدَّم من خلال مشاريع مثل مساعد الأوامر، ليفهم الطالب كيف تستجيب هذه الأدوات للتعليمات بدلًا من التعامل معها كأنها سحر."},{"question":"هل يساعد تعلم Python في المواد الدراسية؟","answer":"ممارسة Python تقوّي التفكير المتسلسل والقراءة الدقيقة والتعامل مع الأرقام، وهي مهارات مفيدة في مواد كثيرة. ويركز الكورس على بناء المهارات والمشاريع، لا على وعود بدرجات معينة."}]}$j$::jsonb,
  guide = $j${"en":[{"heading":"Who this Python course for teens is for","body":"Schowl's Python & AI Foundations is a Python course for teens and pre-teens aged 10 to 18 who are ready to write real, typed code. Students can start from zero. Scratch experience helps younger learners, but it is not required, and older students can begin here directly.\n\nIt suits the student who enjoys puzzles, likes asking what if, or is curious about how apps, games and AI tools actually work. Patient problem solvers do well, and so do students who simply want to build something useful and see it run."},{"heading":"Inside a live 60-minute Python class","body":"Each session is a live, interactive 60 minutes with a real teacher, one-on-one or in a small group of at most four students. The class usually opens with a short recap and a quick challenge, for example predicting what a few lines of code will print. The teacher then introduces one concept, such as a function or a loop, and writes a live example on a shared screen.\n\nNext, students share their own screens and write the code themselves in a code editor. They run it, read the error messages and fix problems step by step, with the teacher asking guiding questions instead of handing over answers. The last minutes are for testing, a short explanation from the student of how their program works, and the next project task."},{"heading":"From core Python to applied projects","body":"The first level, Core Python, covers syntax, logic, functions and simple programs. Students learn to store information in variables, make decisions with conditions, repeat work with loops and organise their code into functions. Early projects include a number guessing game and a simple calculator, small enough to finish but rich enough to practise every core idea.\n\nThe second level, Applied Projects, combines several concepts in one build. Students take on a Pygame challenge, where the same logic drives movement, collisions and scores on screen, and build an AI prompt helper that introduces beginner AI ideas in an age-appropriate way. Difficulty rises gradually, so confidence grows alongside skill."},{"heading":"What students need and how parents stay informed","body":"Students need a laptop or desktop with a stable internet connection and a comfortable keyboard; Python and a code editor are set up with the teacher's help. Screen sharing is used in class so the teacher can read the student's code and debug with them in real time. Headphones with a microphone make the conversation easier.\n\nParents receive parent-friendly progress updates, and every week there is a project with instructor feedback. By the end, the student has a final project they can demonstrate and explain, and they receive a certificate on completion. Classes are scheduled flexibly around school, exams and other activities."},{"heading":"Where to go after Python","body":"Python builds the logic that every other Schowl coding course relies on. Students who loved the Pygame challenge can move into Game Development to build playable prototypes with Unity concepts and C# basics. Those who want to put their work online can continue with Web Development, learning HTML, CSS, JavaScript and React.\n\nStudents who enjoyed building practical tools may prefer Mobile App Development, where they plan and build simple cross-platform apps with Flutter."}],"ar":[{"heading":"لمن صُمم كورس بايثون للمراهقين؟","body":"كورس أساسيات Python والذكاء الاصطناعي في Schowl هو كورس بايثون للمراهقين والطلاب من 10 إلى 18 سنة المستعدين لكتابة كود حقيقي. ويمكن البدء من الصفر؛ فخبرة Scratch مفيدة للطلاب الأصغر سنًا لكنها ليست شرطًا، ويستطيع الطلاب الأكبر أن يبدؤوا هنا مباشرة.\n\nيناسب الكورس الطالب الذي يستمتع بالألغاز ويسأل دائمًا «ماذا لو؟»، أو الفضولي الذي يريد أن يعرف كيف تعمل التطبيقات والألعاب وأدوات الذكاء الاصطناعي من الداخل. وينجح فيه الطالب الصبور على حل المشكلات، كما ينجح فيه من يريد ببساطة أن يبني شيئًا مفيدًا ويراه يعمل."},{"heading":"كيف تسير حصة Python المباشرة؟","body":"كل حصة مدتها 60 دقيقة، مباشرة وتفاعلية مع معلم حقيقي، فردية أو في مجموعة صغيرة لا تتجاوز أربعة طلاب. تبدأ الحصة عادةً بمراجعة قصيرة وتحدٍّ سريع، كأن يتوقع الطالب ما ستطبعه بضعة أسطر من الكود. ثم يشرح المعلم مفهومًا واحدًا، مثل الدالة أو التكرار، ويكتب مثالًا حيًّا على شاشة مشتركة.\n\nبعد ذلك يشارك الطلاب شاشاتهم ويكتبون الكود بأنفسهم في محرر الأكواد، فيشغّلونه ويقرؤون رسائل الخطأ ويصلحون المشكلات خطوة بخطوة، بينما يطرح المعلم أسئلة توجيهية بدلًا من إعطاء الحل جاهزًا. وتُخصَّص الدقائق الأخيرة لاختبار البرنامج، وشرح الطالب لطريقة عمله، وتحديد مهمة المشروع التالية."},{"heading":"من أساسيات Python إلى المشاريع التطبيقية","body":"المستوى الأول، أساسيات Python، يغطي قواعد اللغة والمنطق والدوال والبرامج البسيطة؛ فيتعلم الطالب تخزين البيانات في متغيرات، واتخاذ القرارات بالشروط، وتكرار الأوامر بالحلقات، وتنظيم الكود في دوال. ومن مشاريعه الأولى لعبة تخمين الأرقام وآلة حاسبة بسيطة، وهما مشروعان صغيران يمكن إنهاؤهما لكنهما يغطيان المفاهيم الأساسية كلها.\n\nأما المستوى الثاني، المشاريع التطبيقية، فيجمع أكثر من مفهوم في مشروع واحد. يخوض الطالب تحدي Pygame الذي يحرّك فيه المنطقُ نفسه الشخصياتِ ويكشف التصادم ويحسب النقاط على الشاشة، ويبني مساعد أوامر ذكاء اصطناعي يعرّفه بمبادئ الذكاء الاصطناعي بطريقة مناسبة لعمره. وتزداد الصعوبة تدريجيًا، فتنمو الثقة مع المهارة."},{"heading":"ما يحتاجه الطالب وكيف يتابع ولي الأمر","body":"يحتاج الطالب إلى لابتوب أو كمبيوتر مكتبي مع إنترنت مستقر ولوحة مفاتيح مريحة، ويُجهَّز Python ومحرر الأكواد بمساعدة المعلم. وتُستخدم مشاركة الشاشة في الحصة ليقرأ المعلم كود الطالب ويتتبع الأخطاء معه لحظة بلحظة، ويُفضَّل استخدام سماعة بميكروفون لتسهيل الحوار.\n\nويتلقى ولي الأمر تقارير متابعة واضحة، ويعمل الطالب كل أسبوع على مشروع يحصل فيه على ملاحظات المعلم. وفي النهاية يمتلك الطالب مشروعًا نهائيًا يعرضه ويشرحه، ويحصل على شهادة إتمام. والمواعيد مرنة لتناسب الدراسة والامتحانات والأنشطة الأخرى."},{"heading":"ماذا بعد Python؟","body":"يبني Python المنطق الذي تعتمد عليه بقية كورسات البرمجة في Schowl. فالطالب الذي استمتع بتحدي Pygame يمكنه الانتقال إلى كورس تطوير الألعاب لبناء نماذج قابلة للعب بمفاهيم Unity وأساسيات C#، ومن يريد نشر أعماله على الإنترنت يمكنه متابعة كورس تطوير مواقع الويب وتعلم HTML وCSS وJavaScript وReact.\n\nأما من أحب بناء الأدوات العملية فقد يناسبه كورس تطوير تطبيقات الموبايل، حيث يخطط ويبني تطبيقات بسيطة متعددة المنصات باستخدام Flutter."}]}$j$::jsonb,
  seo_title = $j${"en":"Python and AI Course for Teens in Egypt | Schowl","ar":"كورس Python والذكاء الاصطناعي للمراهقين في مصر | Schowl"}$j$::jsonb,
  seo_description = $j${"en":"Live Python and beginner AI classes for students aged 10-18. Learn coding fundamentals through logic, games, and practical projects.","ar":"حصص Python ومبادئ الذكاء الاصطناعي لايف للطلاب من 10 إلى 18 سنة لتعلم البرمجة من خلال المنطق والألعاب والمشاريع العملية."}$j$::jsonb,
  page_url = $j${"en":"https://schowl.com/course/python/","ar":"https://schowl.com/ar/course/python/"}$j$::jsonb,
  sort_order = 2,
  active = true,
  updated_at = now()
where slug = 'python';

-- Web Development
update public.courses set slug = 'web'
where slug is null and name_en ilike '%web%'
  and not exists (select 1 from public.courses where slug = 'web')
  and id = (select id from public.courses where slug is null and name_en ilike '%web%' order by created_at limit 1);
insert into public.courses (slug, name_en, name_ar)
select 'web', $t$Web Development$t$, $t$تطوير مواقع الويب$t$
where not exists (select 1 from public.courses where slug = 'web');
update public.courses set
  name_en = $t$Web Development$t$,
  name_ar = $t$تطوير مواقع الويب$t$,
  description = $j${"en":"Students learn how modern websites are structured, styled, and made interactive through real pages and components.","ar":"يتعلم الطلاب كيف تُبنى المواقع الحديثة من حيث الهيكل والتصميم والتفاعل من خلال صفحات ومكونات حقيقية."}$j$::jsonb,
  summary = $j${"en":"Students learn how modern websites are structured, styled, and made interactive through real pages and components.","ar":"يتعلم الطلاب كيف تُبنى المواقع الحديثة من حيث الهيكل والتصميم والتفاعل من خلال صفحات ومكونات حقيقية."}$j$::jsonb,
  category = $j${"en":"Programming","ar":"برمجة"}$j$::jsonb,
  short_title = $j${"en":"Web Development","ar":"تطوير الويب"}$j$::jsonb,
  age_range = $t$10-18$t$,
  min_age = 10,
  max_age = 18,
  icon = $t$web$t$,
  image_url = $t$https://images.unsplash.com/photo-1498050108023-c5249f4df085?auto=format&fit=crop&w=1400&q=80$t$,
  logo_url = $t$https://schowl.com/courses/react-logo.svg$t$,
  fallback_image_url = $t$https://schowl.com/courses/webdev.jpg$t$,
  tools = $j$["HTML","CSS","JavaScript","React"]$j$::jsonb,
  outcomes = $j${"en":["Build responsive pages with HTML and CSS.","Add interactivity with JavaScript.","Create React components and simple web apps."],"ar":["بناء صفحات متجاوبة باستخدام HTML وCSS.","إضافة التفاعل باستخدام JavaScript.","إنشاء مكونات React وتطبيقات ويب بسيطة."]}$j$::jsonb,
  projects = $j${"en":["Portfolio website","Landing page","Interactive app"],"ar":["موقع شخصي","صفحة تعريفية","تطبيق تفاعلي"]}$j$::jsonb,
  levels = $j${"en":[{"title":"Web Basics","description":"Structure, styling, layouts, and responsive design."},{"title":"React Projects","description":"Reusable components, state, and interactive screens."}],"ar":[{"title":"أساسيات الويب","description":"الهيكل والتصميم والتخطيط والتجاوب."},{"title":"مشاريع React","description":"مكونات قابلة لإعادة الاستخدام وحالات وشاشات تفاعلية."}]}$j$::jsonb,
  faqs = $j${"en":[{"question":"Will students publish a real website?","answer":"Students build portfolio-ready pages; publishing depends on the project and parent approval."},{"question":"Does the course start with React immediately?","answer":"No. Students first learn HTML, CSS, layout, and JavaScript basics before React becomes useful."},{"question":"What kind of projects are included?","answer":"Students build landing pages, personal portfolios, interactive tools, and small web app screens."},{"question":"Is web development good for creative students?","answer":"Yes. It combines logic, visual layout, writing, design choices, and real problem solving."},{"question":"Is this web development course suitable for a 10-year-old?","answer":"Yes, for a child who reads comfortably and is happy typing. The course begins with visible, immediate results in HTML and CSS, and the small class size lets the teacher adjust the pace. A younger child with no coding at all may benefit from starting with Scratch, and the trial lesson helps decide."},{"question":"Does my child need to learn design before web development?","answer":"No. Basic layout, colour and spacing are taught as part of building pages. Students who want to go deeper into visual design can take the Digital Design & UI/UX course later or alongside."},{"question":"What is the difference between HTML, CSS and JavaScript?","answer":"HTML gives a page its structure and content, CSS controls how it looks, and JavaScript makes it respond to the user. Students learn all three in that order before moving on to React."}],"ar":[{"question":"هل سينشر الطالب موقعًا حقيقيًا؟","answer":"يبني الطلاب صفحات مناسبة للعرض، والنشر يعتمد على المشروع وموافقة ولي الأمر."},{"question":"هل يبدأ الكورس بـ React مباشرة؟","answer":"لا. يتعلم الطلاب أولًا HTML وCSS والتخطيط وأساسيات JavaScript ثم ينتقلون إلى React عندما يكون مناسبًا."},{"question":"ما نوع المشاريع داخل الكورس؟","answer":"يبني الطلاب صفحات تعريفية ومواقع شخصية وأدوات تفاعلية وشاشات تطبيق ويب بسيطة."},{"question":"هل تطوير الويب مناسب للطلاب المبدعين؟","answer":"نعم. يجمع بين المنطق والتخطيط البصري والكتابة واختيارات التصميم وحل المشكلات."},{"question":"هل يناسب كورس تطوير المواقع طفلًا في العاشرة؟","answer":"نعم، إذا كان يقرأ بسهولة ولا يمانع الكتابة على لوحة المفاتيح. يبدأ الكورس بنتائج مرئية وفورية في HTML وCSS، ويتيح صغر المجموعة للمعلم ضبط الإيقاع. أما الطفل الأصغر الذي لم يبرمج من قبل فقد يستفيد من البدء بـ Scratch، وتساعد الحصة التجريبية في حسم ذلك."},{"question":"هل يجب أن يتعلم الطالب التصميم قبل تطوير المواقع؟","answer":"لا. تُدرَّس أساسيات التخطيط والألوان والمسافات ضمن بناء الصفحات نفسها، ومن يريد التعمق في التصميم البصري يمكنه دراسة كورس التصميم الرقمي و UI/UX لاحقًا أو بالتوازي."},{"question":"ما الفرق بين HTML وCSS وJavaScript؟","answer":"تمنح HTML الصفحة هيكلها ومحتواها، وتتحكم CSS في شكلها، وتجعلها JavaScript تستجيب للمستخدم. ويتعلم الطالب الثلاث بهذا الترتيب قبل الانتقال إلى React."}]}$j$::jsonb,
  guide = $j${"en":[{"heading":"Who this web development course for kids and teens is for","body":"Schowl's Web Development course is for students aged 10 to 18 who want to learn how real websites are built. No previous coding is required: the course starts with the basics of HTML and CSS, so a curious beginner can follow. Students who already know some Scratch or Python will recognise much of the logic when they reach JavaScript.\n\nIt is a strong fit for creative students who care how things look as much as how they work. If your child likes customising, arranging layouts, writing or showing off their ideas, building web pages gives them a place to combine all of that with real code."},{"heading":"What happens in a live 60-minute web class","body":"Each class runs for 60 minutes live online with a real teacher, one-on-one or in a group of up to four students. It usually starts by opening last week's page in the browser and checking what works. The teacher then introduces one new skill, such as a flexible layout, a button that responds to clicks or a React component, and demonstrates it on a shared screen.\n\nStudents then share their screens and build it into their own project in a code editor, refreshing the browser to see every change. When something looks wrong, the teacher shows them how to inspect and fix it rather than fixing it for them. The session closes with a short demo and a clear task for the week."},{"heading":"How the course progresses: from HTML to React","body":"The first level, Web Basics, covers structure, styling, layouts and responsive design. Students learn to organise content with HTML, style it with CSS and make pages that adapt to phones and laptops. JavaScript then adds interactivity: responding to clicks, showing and hiding content and updating the page. A landing page is a typical first build.\n\nThe second level, React Projects, introduces reusable components, state and interactive screens. Students see why React is useful once their pages grow, and they build a personal portfolio website and an interactive app. By the end, they understand how a modern website is structured, styled and made interactive, and they can explain the choices behind their own work."},{"heading":"What students need and how parents follow along","body":"A laptop or desktop with a stable internet connection, a modern web browser and a code editor are all that is needed, and the teacher helps set everything up in the first sessions. Screen sharing is used so the teacher can see the student's code and the finished page side by side.\n\nEvery week brings a project with instructor feedback, and parents receive parent-friendly progress updates. The portfolio website becomes a natural showcase: the student can walk you through it and explain how each part was built. Students receive a certificate on completion, and classes are scheduled flexibly. Publishing a site online depends on the project and parent approval."},{"heading":"What to learn after web development","body":"Students who enjoy building screens can continue with Schowl's Mobile App Development course, where the same thinking about layouts, components and user flow is applied to apps built with Flutter.\n\nStudents who discover they love the visual side can take Digital Design & UI/UX to learn layout, hierarchy and interface design in Figma, which helps their future websites look clearer and more professional."}],"ar":[{"heading":"لمن صُمم كورس تطوير المواقع؟","body":"كورس تطوير مواقع الويب في Schowl موجّه للطلاب من 10 إلى 18 سنة الذين يريدون تعلم تطوير المواقع كما تُبنى في الواقع. ولا يشترط الكورس خبرة برمجية سابقة، إذ يبدأ بأساسيات HTML وCSS بحيث يستطيع المبتدئ الفضولي المتابعة، أما من جرّب Scratch أو Python من قبل فسيجد منطق JavaScript مألوفًا.\n\nويناسب الكورس بوجه خاص الطالب المبدع الذي يهتم بشكل الأشياء بقدر اهتمامه بطريقة عملها. فإذا كان طفلك يحب التخصيص وتنسيق الصفحات والكتابة وعرض أفكاره، فإن بناء صفحات الويب يمنحه مساحة تجمع ذلك كله مع كود حقيقي."},{"heading":"كيف تسير حصة تطوير الويب المباشرة؟","body":"مدة كل حصة 60 دقيقة أونلاين بشكل مباشر مع معلم حقيقي، فردية أو في مجموعة لا تزيد على أربعة طلاب. تبدأ الحصة غالبًا بفتح صفحة الأسبوع الماضي في المتصفح ومراجعة ما يعمل منها، ثم يقدّم المعلم مهارة جديدة واحدة، مثل تخطيط مرن للصفحة أو زر يستجيب للنقر أو مكوّن React، ويشرحها على شاشة مشتركة.\n\nبعدها يشارك الطلاب شاشاتهم ويطبقون المهارة في مشاريعهم داخل محرر الأكواد، ويحدّثون المتصفح ليروا أثر كل تعديل. وعندما يظهر خطأ في الشكل أو السلوك، يعلّمهم المعلم كيف يفحصونه ويصلحونه بأنفسهم بدلًا من إصلاحه نيابةً عنهم. وتُختتم الحصة بعرض قصير ومهمة واضحة للأسبوع."},{"heading":"مراحل الكورس: من HTML إلى React","body":"المستوى الأول، أساسيات الويب، يشمل الهيكل والتصميم والتخطيط والتجاوب؛ فيتعلم الطالب تنظيم المحتوى بـ HTML، وتنسيقه بـ CSS، وبناء صفحات تتكيف مع شاشات الموبايل واللابتوب. ثم تضيف JavaScript التفاعل: الاستجابة للنقر، وإظهار المحتوى وإخفاؤه، وتحديث الصفحة. والصفحة التعريفية مثال معتاد على أول مشروع.\n\nأما المستوى الثاني، مشاريع React، فيقدّم المكونات القابلة لإعادة الاستخدام والحالة والشاشات التفاعلية. يدرك الطالب هنا فائدة React حين تكبر صفحاته، فيبني موقعًا شخصيًا وتطبيقًا تفاعليًا. وفي النهاية يفهم كيف يُبنى الموقع الحديث ويُنسَّق ويصبح تفاعليًا، ويستطيع أن يشرح الأسباب وراء اختياراته."},{"heading":"ما يحتاجه الطالب وكيف يتابع ولي الأمر","body":"كل ما يلزم هو لابتوب أو كمبيوتر مكتبي مع إنترنت مستقر، ومتصفح حديث، ومحرر أكواد يساعد المعلم في تجهيزه خلال الحصص الأولى. وتُستخدم مشاركة الشاشة ليرى المعلم كود الطالب والصفحة الناتجة جنبًا إلى جنب.\n\nوفي كل أسبوع مشروع يتلقى عليه الطالب ملاحظات المعلم، ويحصل ولي الأمر على تقارير متابعة واضحة. ويصبح الموقع الشخصي واجهة طبيعية لعرض ما تعلمه، إذ يستطيع الطالب أن يأخذك في جولة داخله ويشرح كيف بُني كل جزء. ويحصل الطالب على شهادة إتمام، والمواعيد مرنة، أما نشر الموقع على الإنترنت فيعتمد على طبيعة المشروع وموافقة ولي الأمر."},{"heading":"ماذا بعد تطوير المواقع؟","body":"الطالب الذي يستمتع ببناء الشاشات يمكنه الانتقال إلى كورس تطوير تطبيقات الموبايل في Schowl، حيث يطبّق التفكير نفسه في التخطيط والمكونات وتدفق المستخدم على تطبيقات تُبنى باستخدام Flutter.\n\nأما من اكتشف شغفه بالجانب البصري فيمكنه دراسة كورس التصميم الرقمي و UI/UX لتعلم التخطيط والترتيب البصري وتصميم الواجهات في Figma، فتبدو مواقعه القادمة أوضح وأكثر احترافية."}]}$j$::jsonb,
  seo_title = $j${"en":"Web Development Course for Kids and Teens in Egypt | Schowl","ar":"كورس تطوير مواقع للأطفال والمراهقين في مصر | Schowl"}$j$::jsonb,
  seo_description = $j${"en":"Live web development classes for students aged 10-18 covering HTML, CSS, JavaScript, and React projects.","ar":"حصص لايف لتطوير الويب للطلاب من 10 إلى 18 سنة تشمل HTML وCSS وJavaScript ومشاريع React."}$j$::jsonb,
  page_url = $j${"en":"https://schowl.com/course/web/","ar":"https://schowl.com/ar/course/web/"}$j$::jsonb,
  sort_order = 3,
  active = true,
  updated_at = now()
where slug = 'web';

-- Game Development
update public.courses set slug = 'game'
where slug is null and name_en ilike '%game%'
  and not exists (select 1 from public.courses where slug = 'game')
  and id = (select id from public.courses where slug is null and name_en ilike '%game%' order by created_at limit 1);
insert into public.courses (slug, name_en, name_ar)
select 'game', $t$Game Development$t$, $t$تطوير الألعاب$t$
where not exists (select 1 from public.courses where slug = 'game');
update public.courses set
  name_en = $t$Game Development$t$,
  name_ar = $t$تطوير الألعاب$t$,
  description = $j${"en":"A creative path for students who want to learn programming by designing levels, rules, and playable experiences.","ar":"مسار إبداعي للطلاب الذين يريدون تعلم البرمجة من خلال تصميم مراحل وقواعد وتجارب لعب."}$j$::jsonb,
  summary = $j${"en":"A creative path for students who want to learn programming by designing levels, rules, and playable experiences.","ar":"مسار إبداعي للطلاب الذين يريدون تعلم البرمجة من خلال تصميم مراحل وقواعد وتجارب لعب."}$j$::jsonb,
  category = $j${"en":"Programming","ar":"برمجة"}$j$::jsonb,
  short_title = $j${"en":"Game Development","ar":"تطوير الألعاب"}$j$::jsonb,
  age_range = $t$10-18$t$,
  min_age = 10,
  max_age = 18,
  icon = $t$game$t$,
  image_url = $t$https://images.unsplash.com/photo-1550745165-9bc0b252726f?auto=format&fit=crop&w=1400&q=80$t$,
  logo_url = $t$https://schowl.com/courses/unity.png$t$,
  fallback_image_url = $t$https://schowl.com/courses/unityd.jpg$t$,
  tools = $j$["Unity","Game Logic","Level Design","C# Basics"]$j$::jsonb,
  outcomes = $j${"en":["Understand game loops, rules, collisions, and scoring.","Design levels and interactive mechanics.","Build playable game prototypes."],"ar":["فهم حلقات اللعب والقواعد والتصادم والنقاط.","تصميم مراحل وآليات تفاعلية.","بناء نماذج ألعاب قابلة للتجربة."]}$j$::jsonb,
  projects = $j${"en":["Obstacle runner","Platformer level","Score challenge"],"ar":["لعبة تفادي العقبات","مرحلة بلاتفورمر","تحدي نقاط"]}$j$::jsonb,
  levels = $j${"en":[{"title":"Game Logic","description":"Rules, input, scoring, collisions, and feedback."},{"title":"Playable Prototype","description":"A small game loop with levels, goals, and polish."}],"ar":[{"title":"منطق الألعاب","description":"القواعد والإدخال والنقاط والتصادم والتغذية الراجعة."},{"title":"نموذج قابل للعب","description":"حلقة لعب صغيرة فيها مراحل وأهداف وتحسينات."}]}$j$::jsonb,
  faqs = $j${"en":[{"question":"Is game development only for advanced students?","answer":"No. Students can start with simple mechanics and grow into more advanced systems."},{"question":"Will students only play games?","answer":"No. They design rules, test mechanics, fix bugs, and explain how their game works."},{"question":"Does the course teach coding?","answer":"Yes. Game projects are used to teach logic, variables, conditions, input, scoring, and feedback."},{"question":"Is Unity required from day one?","answer":"The path can start with simpler game logic first, then move into Unity-style concepts when the student is ready."},{"question":"Is game development a good use of screen time?","answer":"Yes. Unlike playing, building a game asks students to plan rules, write logic, test and explain their thinking. Screen time becomes creative and active, with a clear project to show at the end of each week."},{"question":"What is the difference between game design and game development?","answer":"Game design is deciding the rules, levels and goals; game development is building them with code. This course teaches both, so students learn to plan a level and then make it actually work."},{"question":"Can my child build their own game idea?","answer":"Yes. The course projects give a clear structure, and within them students choose their own characters, levels and rules, while the teacher helps turn those ideas into working mechanics."}],"ar":[{"question":"هل تطوير الألعاب للمتقدمين فقط؟","answer":"لا. يمكن للطلاب البدء بآليات بسيطة ثم الانتقال إلى أنظمة أكثر تقدمًا."},{"question":"هل سيقضي الطالب الحصة في لعب الألعاب فقط؟","answer":"لا. يصمم الطالب القواعد ويختبر آليات اللعب ويصلح الأخطاء ويشرح كيف تعمل لعبته."},{"question":"هل الكورس يعلّم البرمجة فعلًا؟","answer":"نعم. نستخدم مشاريع الألعاب لتعليم المنطق والمتغيرات والشروط والإدخال والنقاط والتفاعل."},{"question":"هل Unity مطلوب من أول حصة؟","answer":"يمكن أن يبدأ المسار بمنطق ألعاب أبسط أولًا، ثم ينتقل إلى مفاهيم Unity عندما يكون الطالب جاهزًا."},{"question":"هل تطوير الألعاب استخدام مفيد لوقت الشاشة؟","answer":"نعم. فعلى عكس اللعب، تتطلب صناعة اللعبة من الطالب أن يخطط القواعد ويكتب المنطق ويختبر ويشرح تفكيره، فيتحول وقت الشاشة إلى وقت إبداعي نشط ينتهي كل أسبوع بمشروع واضح."},{"question":"ما الفرق بين تصميم الألعاب وتطويرها؟","answer":"تصميم الألعاب هو تحديد القواعد والمراحل والأهداف، وتطويرها هو بناء ذلك بالكود. ويجمع هذا الكورس بين الجانبين، فيتعلم الطالب كيف يخطط مرحلة ثم يجعلها تعمل فعلًا."},{"question":"هل يستطيع طفلي تنفيذ فكرة لعبته الخاصة؟","answer":"نعم. تمنح مشاريع الكورس إطارًا واضحًا، وداخله يختار الطالب الشخصيات والمراحل والقواعد، ويساعده المعلم على تحويل أفكاره إلى آليات تعمل."}]}$j$::jsonb,
  guide = $j${"en":[{"heading":"Who this game development course is for","body":"Schowl's Game Development course is for students aged 10 to 18 who would rather build games than just play them. It is a game design course for kids and teens that teaches real programming through levels, rules and playable experiences. Students can start with simple mechanics, so advanced experience is not required.\n\nIt suits the child who invents their own game rules, sketches levels on paper, or notices why one game feels fair and another feels frustrating. Patience and curiosity matter more than prior knowledge, because much of game development is testing an idea, seeing what breaks and improving it."},{"heading":"What a live 60-minute game development class looks like","body":"Every class is 60 minutes, live with a real teacher, one-on-one or with at most four students. The session often starts by playing the student's current build together and naming one thing to improve. The teacher then introduces one mechanic, such as jumping, collecting items or detecting a collision, and shows how it works on a shared screen.\n\nStudents then share their screens and add the mechanic to their own game, adjusting the logic, the level layout and the values until it feels right. They test, fix bugs and explain how their rules work. The class ends with a quick playtest and a goal for the week's project."},{"heading":"How the course progresses: from game logic to a playable prototype","body":"The first level, Game Logic, covers rules, input, scoring, collisions and feedback. Students learn how a game reads the player's keys, how it knows two objects have touched, and how it rewards or challenges the player. The path can begin with simpler game logic before moving into Unity concepts and C# basics when the student is ready.\n\nThe second level, Playable Prototype, brings everything together in a small game loop with levels, goals and polish. Projects include an obstacle runner, a platformer level and a score challenge. Students practise level design, balance difficulty and learn that a good game is built through many rounds of testing and refinement."},{"heading":"What students need and how parents follow progress","body":"Students need a laptop or desktop computer with a stable internet connection, and the teacher guides the setup of the tools used in class. Screen sharing is used in every session so the teacher can see the game running and the logic behind it.\n\nParents get parent-friendly progress updates and can see real results: each week produces a project with instructor feedback, and the course ends with a playable prototype your child can let you try and explain. A certificate is awarded on completion, and scheduling is flexible around school."},{"heading":"What to learn after game development","body":"Game development pairs naturally with Python & AI Foundations, where students strengthen the core programming logic behind their games and build tools and beginner AI experiments.\n\nStudents who enjoyed shaping how their game looks and feels can also explore Digital Design & UI/UX to learn layout, colour and interface design in Figma, skills that make menus, screens and game presentations clearer."}],"ar":[{"heading":"لمن صُمم كورس تطوير الألعاب؟","body":"كورس تطوير الألعاب في Schowl موجّه للطلاب من 10 إلى 18 سنة الذين يفضّلون صناعة الألعاب على مجرد لعبها. وهو مدخل إلى تصميم الألعاب للأطفال والمراهقين يعلّم البرمجة الحقيقية من خلال المراحل والقواعد وتجارب اللعب. ويمكن البدء بآليات بسيطة، فلا يشترط الكورس خبرة متقدمة.\n\nويناسب الطفل الذي يخترع قواعد ألعابه بنفسه، أو يرسم المراحل على الورق، أو يلاحظ لماذا تبدو لعبة ما عادلة وأخرى محبطة. فالصبر والفضول أهم هنا من المعرفة المسبقة، لأن جزءًا كبيرًا من تطوير الألعاب هو تجربة الفكرة، واكتشاف ما يتعطل، ثم تحسينه."},{"heading":"كيف تسير حصة تطوير الألعاب المباشرة؟","body":"مدة كل حصة 60 دقيقة، مباشرة مع معلم حقيقي، فردية أو مع أربعة طلاب على الأكثر. وكثيرًا ما تبدأ بتجربة النسخة الحالية من لعبة الطالب معًا وتحديد نقطة واحدة للتحسين، ثم يقدّم المعلم آلية جديدة، مثل القفز أو جمع العناصر أو اكتشاف التصادم، ويشرح طريقة عملها على شاشة مشتركة.\n\nبعد ذلك يشارك الطلاب شاشاتهم ويضيفون الآلية إلى ألعابهم، فيعدّلون المنطق وتصميم المرحلة والقيم حتى تصبح التجربة ممتعة ومتوازنة. ثم يختبرون ويصلحون الأخطاء ويشرحون كيف تعمل قواعدهم. وتنتهي الحصة بتجربة لعب سريعة وهدف واضح لمشروع الأسبوع."},{"heading":"مراحل الكورس: من منطق الألعاب إلى نموذج قابل للعب","body":"المستوى الأول، منطق الألعاب، يغطي القواعد والإدخال والنقاط والتصادم والتغذية الراجعة؛ فيتعلم الطالب كيف تقرأ اللعبة أزرار اللاعب، وكيف تعرف أن جسمين تلامسا، وكيف تكافئ اللاعب أو تضع أمامه التحديات. ويمكن أن يبدأ المسار بمنطق ألعاب أبسط، ثم ينتقل إلى مفاهيم Unity وأساسيات C# عندما يكون الطالب مستعدًا.\n\nأما المستوى الثاني، النموذج القابل للعب، فيجمع كل ذلك في حلقة لعب صغيرة فيها مراحل وأهداف وتحسينات. ومن مشاريعه لعبة تفادي العقبات، ومرحلة بلاتفورمر، وتحدي نقاط. ويتدرب الطالب على تصميم المراحل وضبط مستوى الصعوبة، ويتعلم أن اللعبة الجيدة تُبنى عبر جولات متكررة من الاختبار والتحسين."},{"heading":"ما يحتاجه الطالب وكيف يتابع ولي الأمر","body":"يحتاج الطالب إلى لابتوب أو كمبيوتر مكتبي مع اتصال إنترنت مستقر، ويرشده المعلم في تجهيز الأدوات المستخدمة في الحصص. وتُستخدم مشاركة الشاشة في كل حصة ليرى المعلم اللعبة وهي تعمل والمنطق الذي يحركها.\n\nويتلقى ولي الأمر تقارير متابعة واضحة، ويرى نتائج ملموسة: ففي كل أسبوع مشروع يحصل فيه الطالب على ملاحظات المعلم، وفي نهاية الكورس نموذج قابل للعب يدعوك طفلك لتجربته ويشرح لك طريقة عمله. ويحصل الطالب على شهادة إتمام، والمواعيد مرنة بما يناسب الدراسة."},{"heading":"ماذا بعد تطوير الألعاب؟","body":"يتكامل تطوير الألعاب بشكل طبيعي مع كورس أساسيات Python والذكاء الاصطناعي، حيث يقوّي الطالب منطق البرمجة الذي تقوم عليه ألعابه، ويبني أدوات وتجارب أولية في الذكاء الاصطناعي.\n\nأما من استمتع بتصميم شكل لعبته وإحساسها فيمكنه دراسة كورس التصميم الرقمي و UI/UX لتعلم التخطيط والألوان وتصميم الواجهات في Figma، وهي مهارات تجعل القوائم والشاشات وعروض الألعاب أوضح."}]}$j$::jsonb,
  seo_title = $j${"en":"Game Development Course for Teens in Egypt | Schowl","ar":"كورس تطوير الألعاب للمراهقين في مصر | Schowl"}$j$::jsonb,
  seo_description = $j${"en":"Live game development classes for students aged 10-18 using Unity concepts, logic, and interactive projects.","ar":"حصص لايف لتطوير الألعاب للطلاب من 10 إلى 18 سنة باستخدام مفاهيم Unity والمنطق والمشاريع التفاعلية."}$j$::jsonb,
  page_url = $j${"en":"https://schowl.com/course/game/","ar":"https://schowl.com/ar/course/game/"}$j$::jsonb,
  sort_order = 4,
  active = true,
  updated_at = now()
where slug = 'game';

-- Mobile App Development
