  and not exists (select 1 from public.courses where slug = 'mobile')
  and id = (select id from public.courses where slug is null and name_en ilike '%mobile%' order by created_at limit 1);
insert into public.courses (slug, name_en, name_ar)
select 'mobile', $t$Mobile App Development$t$, $t$تطوير تطبيقات الموبايل$t$
where not exists (select 1 from public.courses where slug = 'mobile');
update public.courses set
  name_en = $t$Mobile App Development$t$,
  name_ar = $t$تطوير تطبيقات الموبايل$t$,
  description = $j${"en":"Students learn how mobile apps are planned, designed, and built through simple cross-platform app projects.","ar":"يتعلم الطلاب كيف تُخطط وتُصمم وتُبنى تطبيقات الموبايل من خلال مشاريع بسيطة متعددة المنصات."}$j$::jsonb,
  summary = $j${"en":"Students learn how mobile apps are planned, designed, and built through simple cross-platform app projects.","ar":"يتعلم الطلاب كيف تُخطط وتُصمم وتُبنى تطبيقات الموبايل من خلال مشاريع بسيطة متعددة المنصات."}$j$::jsonb,
  category = $j${"en":"Programming","ar":"برمجة"}$j$::jsonb,
