  outcomes = $j${"en":["Understand screens, widgets, and app flow.","Build clean mobile interfaces.","Create simple cross-platform app prototypes."],"ar":["فهم الشاشات والودجتس وتدفق التطبيق.","بناء واجهات موبايل مرتبة.","إنشاء نماذج تطبيقات بسيطة متعددة المنصات."]}$j$::jsonb,
  projects = $j${"en":["Habit tracker","Simple store app","Student helper app"],"ar":["متتبع عادات","تطبيق متجر بسيط","تطبيق مساعد للطلاب"]}$j$::jsonb,
  levels = $j${"en":[{"title":"App Foundations","description":"Screens, components, navigation, and app structure."},{"title":"Prototype Build","description":"A small app with realistic screens and interactions."}],"ar":[{"title":"أساسيات التطبيقات","description":"الشاشات والمكونات والتنقل وهيكل التطبيق."},{"title":"بناء نموذج","description":"تطبيق صغير بشاشات وتفاعلات واقعية."}]}$j$::jsonb,
  faqs = $j${"en":[{"question":"Will this cover publishing to app stores?","answer":"The course focuses first on learning and building. Publishing can be discussed later with parents."},{"question":"Does my child need a phone to learn mobile apps?","answer":"A laptop is the main device. A phone can help with testing later, but it is not the starting requirement."},{"question":"What does the student learn besides code?","answer":"Students learn app flow, screen structure, simple UI choices, and how users move through an app."},{"question":"Is mobile development better after web or Python?","answer":"It depends on the student. The trial and course finder help decide whether mobile apps are the right first path."},{"question":"What is Flutter and why is it used in this course?","answer":"Flutter is a toolkit for building apps from one codebase for more than one platform. Its widget-based approach lets students see a screen take shape piece by piece, which makes app structure easier to understand for beginners."},{"question":"Does my child need to know Dart before starting?","answer":"No. Dart basics are taught inside the course, as each app feature needs them, so students learn the language by using it in their own projects."},{"question":"Can my child build an app for their own idea?","answer":"The course projects provide structure, and students can bring their own ideas into the design of their app within them. Planning their own screens and user flow is part of the learning."}],"ar":[{"question":"هل يشمل الكورس النشر على متاجر التطبيقات؟","answer":"يركز الكورس أولًا على التعلم والبناء، ويمكن مناقشة النشر لاحقًا مع ولي الأمر."},{"question":"هل يحتاج طفلي إلى موبايل لتعلم التطبيقات؟","answer":"اللابتوب هو الجهاز الأساسي. يمكن استخدام الموبايل للاختبار لاحقًا، لكنه ليس شرط البداية."},{"question":"ماذا يتعلم الطالب بجانب الكود؟","answer":"يتعلم الطالب تدفق التطبيق وبناء الشاشات واختيارات واجهة بسيطة وكيف ينتقل المستخدم داخل التطبيق."},{"question":"هل الأفضل تعلم الموبايل بعد الويب أو Python؟","answer":"يعتمد على الطالب. الحصة التجريبية واختبار اختيار الكورس يساعداننا في تحديد المسار الأنسب."},{"question":"ما Flutter ولماذا يُستخدم في هذا الكورس؟","answer":"Flutter أداة لبناء التطبيقات بكود واحد يعمل على أكثر من منصة. وطريقته القائمة على الودجتس تجعل الطالب يرى الشاشة تتشكل قطعة بعد قطعة، فيسهل على المبتدئ فهم هيكل التطبيق."},{"question":"هل يجب أن يعرف طفلي لغة Dart قبل البدء؟","answer":"لا. تُدرَّس أساسيات Dart داخل الكورس كلما احتاجتها ميزة في التطبيق، فيتعلم الطالب اللغة من خلال استخدامها في مشاريعه."},{"question":"هل يستطيع طفلي بناء تطبيق لفكرته الخاصة؟","answer":"تمنح مشاريع الكورس إطارًا واضحًا، ويستطيع الطالب داخله أن يضيف أفكاره الخاصة إلى تصميم تطبيقه، فالتخطيط لشاشاته وتدفق المستخدم فيها جزء أساسي من التعلم."}]}$j$::jsonb,
  guide = $j${"en":[{"heading":"Who this mobile app development course is for","body":"Schowl's Mobile App Development course is for students aged 10 to 18 who use apps every day and want to learn how to make their own. It teaches mobile app development for teens and pre-teens through simple cross-platform projects built with Flutter and the basics of the Dart language. Prior coding helps but is not required for a motivated beginner, and the trial lesson helps decide whether mobile apps are the right first path.\n\nIt suits the practical, product-minded student: the one who has ideas for an app that would help with homework, habits or a small business, and who cares about how an app feels to use, not only how it works."},{"heading":"What a live 60-minute app class looks like","body":"Each class lasts 60 minutes, live online with a real teacher, one-on-one or in a small group of at most four students. It usually begins by running the student's app from last week and looking at one screen that could be clearer. The teacher then introduces one idea, such as a new widget, a list or navigation between screens, and builds a short example on a shared screen.\n\nThe student then shares their screen and adds that piece to their own app, previewing the result and fixing layout or logic issues with the teacher's guidance. Before the hour ends, the student explains how a user will move through the new feature, and the teacher sets the next step of the weekly project."},{"heading":"How the course progresses: from app foundations to a working prototype","body":"The first level, App Foundations, covers screens, components, navigation and app structure. Students learn how an app is planned before it is coded: which screens it needs, what each screen shows and how the user moves between them. In Flutter, they build interfaces from widgets and write simple Dart logic to make them respond.\n\nThe second level, Prototype Build, turns that knowledge into a small app with realistic screens and interactions. Projects include a habit tracker, a simple store app and a student helper app. Alongside code, students practise clean mobile interfaces, simple UI choices and thinking about the person who will use the app."},{"heading":"What students need and how parents follow progress","body":"A laptop or desktop with a stable internet connection is the main device; a phone can help with testing later but is not needed to start. The teacher helps set up the tools, and screen sharing is used in class so the teacher can see both the code and the app preview.\n\nParents receive parent-friendly progress updates, and each week the student completes a project with instructor feedback. The course ends with a final app prototype the student can demonstrate and explain, and a certificate on completion. Scheduling is flexible to fit around school and other activities."},{"heading":"What to learn after mobile app development","body":"Students who want their ideas to open in any browser can continue with Schowl's Web Development course, learning HTML, CSS, JavaScript and React. Those who enjoyed shaping how their app looks can take Digital Design & UI/UX, where they design app screens and user flows in Figma before building them.\n\nStudents who want stronger programming logic may benefit from Python & AI Foundations, which deepens problem solving through games, tools and beginner AI projects."}],"ar":[{"heading":"لمن صُمم كورس برمجة تطبيقات الموبايل؟","body":"كورس تطوير تطبيقات الموبايل في Schowl موجّه للطلاب من 10 إلى 18 سنة الذين يستخدمون التطبيقات يوميًا ويريدون أن يصنعوا تطبيقاتهم الخاصة. ويعلّم الكورس برمجة تطبيقات الموبايل من خلال مشاريع بسيطة متعددة المنصات تُبنى باستخدام Flutter وأساسيات لغة Dart. والخبرة البرمجية السابقة مفيدة لكنها ليست شرطًا للمبتدئ المتحمس، وتساعد الحصة التجريبية في تحديد ما إذا كانت التطبيقات هي البداية الأنسب.\n\nويناسب الكورس الطالب العملي صاحب الأفكار: من يفكر في تطبيق يساعد في المذاكرة أو تنظيم العادات أو إدارة مشروع صغير، ويهتم بتجربة استخدام التطبيق لا بطريقة عمله فقط."},{"heading":"كيف تسير حصة التطبيقات المباشرة؟","body":"مدة كل حصة 60 دقيقة أونلاين بشكل مباشر مع معلم حقيقي، فردية أو في مجموعة صغيرة لا تتجاوز أربعة طلاب. تبدأ عادةً بتشغيل تطبيق الطالب من الأسبوع الماضي والنظر في شاشة يمكن أن تصبح أوضح، ثم يقدّم المعلم فكرة واحدة، مثل ودجت جديدة أو قائمة أو التنقل بين الشاشات، ويبني مثالًا قصيرًا على شاشة مشتركة.\n\nبعد ذلك يشارك الطالب شاشته ويضيف هذا الجزء إلى تطبيقه، فيعاين النتيجة ويصلح مشكلات التخطيط أو المنطق بتوجيه من المعلم. وقبل نهاية الحصة يشرح الطالب كيف سيتنقل المستخدم داخل الميزة الجديدة، ويحدد المعلم الخطوة التالية في المشروع الأسبوعي."},{"heading":"مراحل الكورس: من أساسيات التطبيقات إلى نموذج يعمل","body":"المستوى الأول، أساسيات التطبيقات، يشمل الشاشات والمكونات والتنقل وهيكل التطبيق. يتعلم الطالب كيف يُخطَّط التطبيق قبل كتابة الكود: ما الشاشات التي يحتاجها، وماذا تعرض كل شاشة، وكيف ينتقل المستخدم بينها. ثم يبني الواجهات في Flutter من الودجتس، ويكتب منطقًا بسيطًا بلغة Dart لتستجيب للمستخدم.\n\nأما المستوى الثاني، بناء نموذج، فيحوّل هذه المعرفة إلى تطبيق صغير بشاشات وتفاعلات واقعية. ومن مشاريعه متتبع عادات، وتطبيق متجر بسيط، وتطبيق مساعد للطلاب. وإلى جانب الكود يتدرب الطالب على بناء واجهات موبايل مرتبة، واتخاذ قرارات تصميم بسيطة، والتفكير في الشخص الذي سيستخدم التطبيق."},{"heading":"ما يحتاجه الطالب وكيف يتابع ولي الأمر","body":"الجهاز الأساسي هو لابتوب أو كمبيوتر مكتبي مع إنترنت مستقر، أما الموبايل فقد يفيد في الاختبار لاحقًا لكنه ليس شرطًا للبداية. ويساعد المعلم في تجهيز الأدوات، وتُستخدم مشاركة الشاشة ليرى المعلم الكود ومعاينة التطبيق معًا.\n\nويتلقى ولي الأمر تقارير متابعة واضحة، وفي كل أسبوع ينجز الطالب مشروعًا يحصل فيه على ملاحظات المعلم. وينتهي الكورس بنموذج تطبيق نهائي يعرضه الطالب ويشرحه، مع شهادة إتمام. والمواعيد مرنة بما يناسب الدراسة والأنشطة الأخرى."},{"heading":"ماذا بعد تطوير التطبيقات؟","body":"الطالب الذي يريد أن تُفتح أفكاره في أي متصفح يمكنه متابعة كورس تطوير مواقع الويب في Schowl وتعلم HTML وCSS وJavaScript وReact. ومن استمتع بتشكيل مظهر تطبيقه يمكنه دراسة كورس التصميم الرقمي و UI/UX، حيث يصمم شاشات التطبيقات وتدفقات المستخدم في Figma قبل برمجتها.\n\nأما من يريد تقوية منطقه البرمجي فقد يناسبه كورس أساسيات Python والذكاء الاصطناعي، الذي يعمّق مهارة حل المشكلات من خلال الألعاب والأدوات ومشاريع الذكاء الاصطناعي الأولية."}]}$j$::jsonb,
  seo_title = $j${"en":"Mobile App Development Course for Teens in Egypt | Schowl","ar":"كورس تطوير تطبيقات الموبايل للمراهقين في مصر | Schowl"}$j$::jsonb,
  seo_description = $j${"en":"Live mobile app development classes for students aged 10-18 using Flutter concepts and app-building projects.","ar":"حصص لايف لتطوير تطبيقات الموبايل للطلاب من 10 إلى 18 سنة باستخدام مفاهيم Flutter ومشاريع تطبيقية."}$j$::jsonb,
  page_url = $j${"en":"https://schowl.com/course/mobile/","ar":"https://schowl.com/ar/course/mobile/"}$j$::jsonb,
  sort_order = 5,
  active = true,
  updated_at = now()
where slug = 'mobile';

-- Digital Design & UI/UX
update public.courses set slug = 'graphic'
where slug is null and (name_en ilike '%graphic%' or name_en ilike '%design%') and name_en not ilike '%web%' and name_en not ilike '%game%'
  and not exists (select 1 from public.courses where slug = 'graphic')
  and id = (select id from public.courses where slug is null and (name_en ilike '%graphic%' or name_en ilike '%design%') and name_en not ilike '%web%' and name_en not ilike '%game%' order by created_at limit 1);
insert into public.courses (slug, name_en, name_ar)
select 'graphic', $t$Digital Design & UI/UX$t$, $t$التصميم الرقمي و UI/UX$t$
where not exists (select 1 from public.courses where slug = 'graphic');
update public.courses set
  name_en = $t$Digital Design & UI/UX$t$,
  name_ar = $t$التصميم الرقمي و UI/UX$t$,
  description = $j${"en":"A creative design path where students learn visual thinking, layout, branding basics, and interface design with Figma.","ar":"مسار تصميم إبداعي يتعلم فيه الطلاب التفكير البصري والتخطيط وأساسيات الهوية وتصميم الواجهات باستخدام Figma."}$j$::jsonb,
  summary = $j${"en":"A creative design path where students learn visual thinking, layout, branding basics, and interface design with Figma.","ar":"مسار تصميم إبداعي يتعلم فيه الطلاب التفكير البصري والتخطيط وأساسيات الهوية وتصميم الواجهات باستخدام Figma."}$j$::jsonb,
  category = $j${"en":"Design","ar":"تصميم"}$j$::jsonb,
  short_title = $j${"en":"Digital Design","ar":"التصميم الرقمي"}$j$::jsonb,
  age_range = $t$10-18$t$,
  min_age = 10,
  max_age = 18,
  icon = $t$graphic$t$,
  image_url = $t$https://images.unsplash.com/photo-1561070791-2526d30994b5?auto=format&fit=crop&w=1400&q=80$t$,
  logo_url = $t$https://schowl.com/courses/Figma-logo.png$t$,
  fallback_image_url = $t$https://schowl.com/courses/graphic.jpg$t$,
  tools = $j$["Figma","UI/UX","Branding","Visual Design"]$j$::jsonb,
  outcomes = $j${"en":["Use layout, hierarchy, color, and spacing.","Design app screens and social visuals.","Build a small design portfolio."],"ar":["استخدام التخطيط والترتيب البصري والألوان والمسافات.","تصميم شاشات تطبيقات وتصميمات سوشيال.","بناء ملف أعمال تصميم صغير."]}$j$::jsonb,
  projects = $j${"en":["Mobile app UI","Social media post set","Brand board"],"ar":["واجهة تطبيق موبايل","مجموعة منشورات سوشيال","لوحة هوية بصرية"]}$j$::jsonb,
  levels = $j${"en":[{"title":"Design Foundations","description":"Color, type, spacing, layout, and visual hierarchy."},{"title":"UI/UX Projects","description":"App screens, user flows, and portfolio-ready visuals."}],"ar":[{"title":"أساسيات التصميم","description":"الألوان والخطوط والمسافات والتخطيط والترتيب البصري."},{"title":"مشاريع UI/UX","description":"شاشات تطبيقات وتدفقات مستخدم وتصميمات قابلة للعرض."}]}$j$::jsonb,
  faqs = $j${"en":[{"question":"Is this a drawing course?","answer":"No. It focuses on digital design, layout, interfaces, branding basics, and practical visual projects."},{"question":"What will students design?","answer":"Students design app screens, social media visuals, simple brand boards, and portfolio-ready presentation pieces."},{"question":"Does the course use Figma?","answer":"Yes. Figma is used because it is professional, collaborative, and friendly for beginner digital designers."},{"question":"Is design useful for students who also code?","answer":"Yes. Design helps coding students make clearer websites, apps, and presentations for their projects."},{"question":"What is the difference between graphic design and UI/UX design?","answer":"Graphic design focuses on visuals that communicate a message, such as social posts and brand identity. UI/UX design focuses on how screens look and how easy they are to use. This course covers both, starting with visual foundations and moving into app screens and user flows."},{"question":"Is 10 too young to learn digital design?","answer":"Ten is the starting age for this course. Younger students begin with simpler layouts and more guidance, while older students take on more detailed UI/UX work. The trial lesson helps the teacher set the right starting point."},{"question":"Will my child learn to create a brand identity?","answer":"Yes, at a beginner level. In the brand board project, students choose the colours, fonts and visual style for a brand and explain how they work together."}],"ar":[{"question":"هل هذا كورس رسم؟","answer":"لا. يركز على التصميم الرقمي والتخطيط والواجهات وأساسيات الهوية والمشاريع البصرية العملية."},{"question":"ماذا سيصمم الطلاب؟","answer":"يصمم الطلاب شاشات تطبيقات وتصميمات سوشيال ميديا ولوحات هوية بسيطة وأعمالًا مناسبة للعرض."},{"question":"هل يستخدم الكورس Figma؟","answer":"نعم. نستخدم Figma لأنه أداة احترافية وتعاونية ومناسبة كبداية للطلاب في التصميم الرقمي."},{"question":"هل التصميم مفيد للطلاب الذين يتعلمون البرمجة أيضًا؟","answer":"نعم. يساعد التصميم طلاب البرمجة على بناء مواقع وتطبيقات وعروض مشاريع أوضح وأقوى."},{"question":"ما الفرق بين التصميم الجرافيكي وتصميم UI/UX؟","answer":"يركز التصميم الجرافيكي على العناصر البصرية التي توصل رسالة، مثل منشورات السوشيال ميديا والهوية البصرية، بينما يركز تصميم UI/UX على شكل الشاشات وسهولة استخدامها. ويجمع هذا الكورس بين الاثنين، فيبدأ بالأسس البصرية ثم ينتقل إلى شاشات التطبيقات وتدفقات المستخدم."},{"question":"هل سن العاشرة مبكرة لتعلم التصميم الرقمي؟","answer":"العاشرة هي سن البداية في هذا الكورس. يبدأ الطلاب الأصغر بتخطيطات أبسط وتوجيه أكبر، بينما يتولى الأكبر سنًا أعمال UI/UX أكثر تفصيلًا، وتساعد الحصة التجريبية المعلم في تحديد نقطة البداية المناسبة."},{"question":"هل سيتعلم طفلي بناء هوية بصرية؟","answer":"نعم، على مستوى المبتدئين. ففي مشروع لوحة الهوية البصرية يختار الطالب الألوان والخطوط والأسلوب البصري لعلامة ما، ويشرح كيف تتناسق هذه العناصر معًا."}]}$j$::jsonb,
  guide = $j${"en":[{"heading":"Who this digital design course is for","body":"Schowl's Digital Design & UI/UX course is for students aged 10 to 18 who want to learn graphic design and interface design the way they are practised today, on screen. No drawing talent or prior experience is needed; the course is about layout, colour, type and clear communication rather than sketching skill. That makes it a graphic design course for kids and teens who are starting from zero.\n\nIt suits the child who notices fonts and logos, likes making school presentations look good, or has opinions about which apps look right. It also suits coding students who want their websites and apps to look more professional."},{"heading":"What a live 60-minute design class looks like","body":"Every class is 60 minutes, live online with a real teacher, one-on-one or in a small group of no more than four students. A session often starts by looking at the student's latest design together and asking a simple question: what does the eye see first? The teacher then introduces one principle, such as visual hierarchy, spacing or colour contrast, and demonstrates it in Figma on a shared screen.\n\nStudents then share their screens and apply the principle to their own project, trying variations and comparing them. The teacher gives specific feedback on alignment, readability and consistency. The class closes with each student presenting their design, explaining the decisions behind it and receiving the next step for the weekly project."},{"heading":"How the course progresses: from design foundations to UI/UX projects","body":"The first level, Design Foundations, covers colour, type, spacing, layout and visual hierarchy. Students learn why some designs feel calm and clear while others feel crowded, and how small changes in size, alignment and contrast guide attention. A social media post set is ideal early practice: several posts that share one consistent style.\n\nThe second level, UI/UX Projects, moves to app screens, user flows and portfolio-ready visuals. Students design a mobile app UI, thinking about how a user moves from one screen to the next, and create a brand board that defines colours, fonts and a simple visual identity. Each piece is refined through feedback until it is ready to show."},{"heading":"What students need and how parents follow progress","body":"A laptop or desktop with a stable internet connection and a web browser is enough, since Figma runs online, and the teacher helps the student get started in it during the first class. Screen sharing is used so the teacher can see the design as it takes shape, and a mouse makes precise work easier.\n\nParents receive parent-friendly progress updates, and every week the student completes a project with instructor feedback. The course builds toward a small design portfolio your child can present and explain, plus a certificate on completion. Classes are scheduled flexibly around school."},{"heading":"What to learn after digital design","body":"Designers who want to bring their screens to life can continue with Schowl's Web Development course, turning layouts into real pages with HTML, CSS, JavaScript and React. Students who designed app screens they would like to build can move into Mobile App Development with Flutter.\n\nEither way, the design skills they gained make every future coding project clearer and easier to use."}],"ar":[{"heading":"لمن صُمم كورس التصميم الرقمي؟","body":"كورس التصميم الرقمي و UI/UX في Schowl موجّه للطلاب من 10 إلى 18 سنة الذين يريدون تعلم التصميم الجرافيكي وتصميم الواجهات كما يُمارَس اليوم على الشاشة. ولا يحتاج الطالب إلى موهبة في الرسم أو خبرة سابقة، فالكورس يركز على التخطيط والألوان والخطوط والتواصل البصري الواضح لا على مهارة الرسم اليدوي، ولذلك فهو بداية مناسبة لمن يبدأ من الصفر.\n\nويناسب الطفل الذي يلاحظ الخطوط والشعارات، ويحرص على أن تبدو عروضه المدرسية جميلة، ويبدي رأيه في شكل التطبيقات. كما يناسب طلاب البرمجة الذين يريدون أن تبدو مواقعهم وتطبيقاتهم أكثر احترافية."},{"heading":"كيف تسير حصة التصميم المباشرة؟","body":"مدة كل حصة 60 دقيقة أونلاين بشكل مباشر مع معلم حقيقي، فردية أو في مجموعة صغيرة لا تزيد على أربعة طلاب. وكثيرًا ما تبدأ بمراجعة أحدث تصميم للطالب وسؤال بسيط: ما أول ما تقع عليه العين؟ ثم يقدّم المعلم مبدأً واحدًا، مثل الترتيب البصري أو المسافات أو تباين الألوان، ويطبقه في Figma على شاشة مشتركة.\n\nبعد ذلك يشارك الطلاب شاشاتهم ويطبقون المبدأ على مشاريعهم، فيجربون أكثر من بديل ويقارنون بينها، ويقدّم المعلم ملاحظات محددة على المحاذاة ووضوح القراءة والاتساق. وتُختتم الحصة بعرض كل طالب لتصميمه وشرح قراراته، ثم تحديد الخطوة التالية في المشروع الأسبوعي."},{"heading":"مراحل الكورس: من أساسيات التصميم إلى مشاريع UI/UX","body":"المستوى الأول، أساسيات التصميم، يشمل الألوان والخطوط والمسافات والتخطيط والترتيب البصري. يتعلم الطالب لماذا يبدو تصميم ما هادئًا وواضحًا بينما يبدو غيره مزدحمًا، وكيف توجّه التغييرات الصغيرة في الحجم والمحاذاة والتباين انتباه المشاهد. وتُعد مجموعة منشورات السوشيال ميديا تدريبًا أول مثاليًا: عدة منشورات يجمعها أسلوب واحد متسق.\n\nأما المستوى الثاني، مشاريع UI/UX، فينتقل إلى شاشات التطبيقات وتدفقات المستخدم والتصميمات القابلة للعرض. يصمم الطالب واجهة تطبيق موبايل ويفكر في انتقال المستخدم من شاشة إلى أخرى، وينشئ لوحة هوية بصرية تحدد الألوان والخطوط وهوية بسيطة لعلامة ما. ويُحسَّن كل عمل عبر الملاحظات حتى يصبح جاهزًا للعرض."},{"heading":"ما يحتاجه الطالب وكيف يتابع ولي الأمر","body":"يكفي لابتوب أو كمبيوتر مكتبي مع إنترنت مستقر ومتصفح ويب، لأن Figma يعمل عبر الإنترنت، ويساعد المعلم الطالب على البدء فيه من الحصة الأولى. وتُستخدم مشاركة الشاشة ليتابع المعلم التصميم وهو يتشكل، ويُفضَّل استخدام فأرة لدقة العمل.\n\nويتلقى ولي الأمر تقارير متابعة واضحة، وفي كل أسبوع ينجز الطالب مشروعًا يحصل فيه على ملاحظات المعلم. ويتجه الكورس نحو ملف أعمال تصميم صغير يعرضه الطالب ويشرحه، مع شهادة إتمام. والمواعيد مرنة بما يناسب الدراسة."},{"heading":"ماذا بعد التصميم الرقمي؟","body":"المصمم الذي يريد أن تنبض شاشاته بالحياة يمكنه متابعة كورس تطوير مواقع الويب في Schowl، فيحوّل تصميماته إلى صفحات حقيقية باستخدام HTML وCSS وJavaScript وReact. ومن صمم شاشات تطبيق يتمنى بناءه يمكنه الانتقال إلى كورس تطوير تطبيقات الموبايل باستخدام Flutter.\n\nوفي الحالتين تجعل مهارات التصميم التي اكتسبها كل مشروع برمجي قادم أوضح وأسهل في الاستخدام."}]}$j$::jsonb,
  seo_title = $j${"en":"Digital Design and UI/UX Course for Kids in Egypt | Schowl","ar":"كورس التصميم الرقمي و UI/UX للأطفال في مصر | Schowl"}$j$::jsonb,
  seo_description = $j${"en":"Live digital design and UI/UX classes for students aged 10-18 using Figma, layout, branding, and project-based design.","ar":"حصص لايف للتصميم الرقمي و UI/UX للطلاب من 10 إلى 18 سنة باستخدام Figma والتخطيط والهوية ومشاريع التصميم."}$j$::jsonb,
  page_url = $j${"en":"https://schowl.com/course/graphic/","ar":"https://schowl.com/ar/course/graphic/"}$j$::jsonb,
  sort_order = 6,
  active = true,
  updated_at = now()
where slug = 'graphic';

