  ('one_on_one_12', $t$1-on-1 Project (12 lessons)$t$, 'one_on_one', $t$Project$t$, $t$مشروع$t$, 12, 5700, 'EGP', $j$["All Builder features","Single course","Deeper project build","More review and debugging time","Portfolio-ready milestone"]$j$::jsonb, $j$["جميع مميزات خطة البناء","كورس واحد","بناء مشروع أعمق","وقت أكبر للمراجعة وحل الأخطاء","إنجاز مناسب للعرض"]$j$::jsonb, false, false, 3, 60, true),
  ('one_on_one_24', $t$1-on-1 Portfolio (24 lessons)$t$, 'one_on_one', $t$Portfolio$t$, $t$ملف أعمال$t$, 24, 10500, 'EGP', $j$["All Project features","Longer portfolio track","Can combine two related paths","More structured revision","Best for sustained progress"]$j$::jsonb, $j$["جميع مميزات خطة المشروع","مسار أطول لملف الأعمال","إمكانية الجمع بين مسارين مرتبطين","مراجعة أكثر تنظيمًا","مناسب للتقدم المستمر"]$j$::jsonb, false, true, 4, 60, true),
  ('group_4', $t$Group Starter (4 lessons)$t$, 'group', $t$Starter$t$, $t$بداية$t$, 4, 1200, 'EGP', $j$["Small group live sessions","Collaborative learning","Cost-effective","Single course","Best for trying the first level"]$j$::jsonb, $j$["حصص لايف في مجموعات صغيرة","تعلم تعاوني","تكلفة أقل","كورس واحد","مناسب لتجربة المستوى الأول"]$j$::jsonb, false, false, 11, 60, true),
  ('group_8', $t$Group Builder (8 lessons)$t$, 'group', $t$Builder$t$, $t$بناء$t$, 8, 2200, 'EGP', $j$["All Starter features","Single course","Weekly practice tasks","Group project moments"]$j$::jsonb, $j$["جميع مميزات خطة البداية","كورس واحد","مهام تدريب أسبوعية","لحظات مشروع جماعي"]$j$::jsonb, true, false, 12, 60, true),
  ('group_12', $t$Group Project (12 lessons)$t$, 'group', $t$Project$t$, $t$مشروع$t$, 12, 3200, 'EGP', $j$["All Builder features","Single course","Deeper project build","More practice and review","Portfolio-ready milestone"]$j$::jsonb, $j$["جميع مميزات خطة البناء","كورس واحد","بناء مشروع أعمق","تدريب ومراجعة أكثر","إنجاز مناسب للعرض"]$j$::jsonb, false, false, 13, 60, true)
on conflict (key) where key is not null do update set
