-- ---------------------------------------------------------------------------
-- 3) Trial hours: open 24/7 (every day, 00:00–24:00 Cairo). Slots are a
--    template only: a booking never reserves its hour, so any number of
--    students can book the same time (see trial_slot_load below).
-- ---------------------------------------------------------------------------
delete from public.trial_hours;
insert into public.trial_hours (day_of_week, start_time, end_time, active)
select d, time '00:00', time '24:00', true
from generate_series(0, 6) as d;

-- 24/7 hourly slots over 14 days = 336; raise the old 300-row cap.
create or replace function public.open_trial_slots(
  p_from timestamptz,
  p_to timestamptz,
  p_step integer default 60,
  p_lead_minutes integer default 720,
  p_tz text default 'Africa/Cairo'
)
returns setof timestamptz
language sql
stable
as $fn$
  select gs
  from generate_series(
    date_trunc('hour', greatest(p_from, now())) + make_interval(mins => greatest(15, p_step)),
    p_to,
    make_interval(mins => greatest(15, p_step))
  ) gs
  where gs >= now() + make_interval(mins => greatest(0, p_lead_minutes))
    and exists (
      select 1
      from public.trial_hours th
      where th.active
        and th.day_of_week = extract(dow from (gs at time zone p_tz))::smallint
        and (gs at time zone p_tz)::time >= th.start_time
        and (gs at time zone p_tz)::time < th.end_time
    )
  order by gs
  limit 2000;
$fn$;

-- How many trial students are booked in each hour (for staffing teachers).
create or replace view public.trial_slot_load as
select
  date_trunc('hour', l.scheduled_at) as slot_start,
  count(*) as students,
  count(*) filter (where l.teacher_id is null) as without_teacher
from public.lesson l
where l.lesson_type = 'trial'
  and coalesce(l.status, '') not ilike 'cancel%'
  and l.scheduled_at >= now() - interval '1 day'
group by 1
order by 1;

commit;
